import json,sys;d=json.load(sys.stdin)
def w(o):
  if isinstance(o,dict):
    if 'key' in o or 'Key' in o: print({k:v for k,v in o.items() if k.lower() in('key','cachehit','cache_hit','status','result','cached')})
    for v in o.values(): w(v)
  elif isinstance(o,list):
    for v in o: w(v)
w(d)" | head -20; rwx results --help 2>&1 | grep -iE 'tasks|full' | head

